package commands

// AutoSync placeholder media — copy fail zalelya media sathi same-type chhota "fake" file.
// Message jagevar rahto (order bighadat nahi); pudhchya run madhe asli media ne edit karun replace hoto.
// (Auto-generated tiny files — ~2KB each.)

import (
	"encoding/base64"
	"path"
	"strings"
)

var asPlaceholderB64 = map[string]string{
	"jpg":  "",
	"png":  "",
	"mp4":  "",
	"mkv":  "",
	"webm": "",
	"mp3":  "",
	"pdf":  "JVBERi0xLjEKMSAwIG9iajw8L1R5cGUvQ2F0YWxvZy9QYWdlcyAyIDAgUj4+ZW5kb2JqCjIgMCBvYmo8PC9UeXBlL1BhZ2VzL0tpZHNbMyAwIFJdL0NvdW50IDE+PmVuZG9iagozIDAgb2JqPDwvVHlwZS9QYWdlL1BhcmVudCAyIDAgUi9NZWRpYUJveFswIDAgMjAwIDEwMF0+PmVuZG9iagp0cmFpbGVyPDwvUm9vdCAxIDAgUj4+CiUlRU9GCg==",
}

var asPlaceholderCache = map[string][]byte{}

func asPlaceholderBytes(kind string) []byte {
	if v, ok := asPlaceholderCache[kind]; ok {
		return v
	}
	if s, ok := asPlaceholderB64[kind]; ok {
		if raw, err := base64.StdEncoding.DecodeString(s); err == nil {
			asPlaceholderCache[kind] = raw
			return raw
		}
	}
	return []byte("placeholder — asli file next AutoSync run madhe replace hoil\n")
}

// asPlaceholderFor — file naav + mime varun placeholder (kind, bytes) nivadto. Extension = same type.
func asPlaceholderFor(fileName, mime string) (kind string, data []byte) {
	ext := strings.TrimPrefix(strings.ToLower(path.Ext(fileName)), ".")
	switch ext {
	case "jpg", "jpeg":
		kind = "jpg"
	case "png":
		kind = "png"
	case "mp4", "m4v", "mov", "3gp":
		kind = "mp4"
	case "mkv":
		kind = "mkv"
	case "webm":
		kind = "webm"
	case "mp3":
		kind = "mp3"
	case "pdf":
		kind = "pdf"
	}
	if kind == "" {
		switch strings.ToLower(mime) {
		case "image/jpeg":
			kind = "jpg"
		case "image/png":
			kind = "png"
		case "video/mp4", "video/quicktime":
			kind = "mp4"
		case "video/x-matroska":
			kind = "mkv"
		case "video/webm":
			kind = "webm"
		case "audio/mpeg":
			kind = "mp3"
		case "application/pdf":
			kind = "pdf"
		}
	}
	if kind == "" {
		kind = "txt"
	}
	return kind, asPlaceholderBytes(kind)
}
